import {segmentHit} from './flight.js?v=12';
// Fictional arcade combat: finite projectiles, warning delay and solid cover.
export class PoliceCombat{
 constructor(onEvent=()=>{}){this.onEvent=onEvent;this.bullets=[];this.shots=0;this.warning=0;this.wasArmed=false;}
 update(dt,state,enforcement,obstacles=[],floor=()=>0){const armed=enforcement.active&&enforcement.armed;if(armed&&!this.wasArmed){this.warning=2.2;this.onEvent({type:'warning',message:'武装警戒 · 警察が銃を構えています'});}this.wasArmed=armed;this.warning=Math.max(0,this.warning-dt);
  if(!armed){this.bullets=[];return;}for(const officer of enforcement.officers){officer.gunFlash=Math.max(0,(officer.gunFlash||0)-dt);officer.gunCooldown=Math.max(0,(officer.gunCooldown||0)-dt);if(!officer.visible||officer.destroyed||this.warning>0||officer.gunCooldown>0||this.bullets.length>=12)continue;const origin={x:officer.x,y:officer.y+1.35,z:officer.z},target={x:state.x,y:state.y+(state.onFoot?1.1:.8),z:state.z},distance=Math.hypot(target.x-origin.x,target.y-origin.y,target.z-origin.z);if(distance>85||distance<2||obstacles.some(b=>b!==officer&&!b.destroyed&&segmentHit(origin,target,b)!==null))continue;
   officer.gunCooldown=1.1+officer.index*.15;officer.gunFlash=.1;const spread=.045*Math.sin(++this.shots*2.4),yaw=Math.atan2(-(target.x-origin.x),-(target.z-origin.z))+spread,pitch=Math.atan2(target.y-origin.y,Math.hypot(target.x-origin.x,target.z-origin.z))+.018*Math.cos(this.shots*1.7);this.bullets.push({...origin,vx:-Math.sin(yaw)*Math.cos(pitch)*100,vy:Math.sin(pitch)*100,vz:-Math.cos(yaw)*Math.cos(pitch)*100,life:0,owner:officer});this.onEvent({type:'shot',origin,distance});}
  let subdued=false;this.bullets=this.bullets.filter(b=>{if(subdued)return false;b.life+=dt;const end={x:b.x+b.vx*dt,y:b.y+b.vy*dt,z:b.z+b.vz*dt},player={...state,hx:state.onFoot?.3:state.hx??.88,hz:state.onFoot?.3:state.hz??2.2,height:state.onFoot?1.75:1.7},hit=segmentHit(b,end,player);let solid=end.y<floor(end.x,end.z)?0:Infinity;for(const obstacle of obstacles){if(obstacle===b.owner||obstacle.destroyed)continue;if(Math.abs(obstacle.x-b.x)>(obstacle.hx||1)+4||Math.abs(obstacle.z-b.z)>(obstacle.hz||1)+4)continue;const t=segmentHit(b,end,obstacle);if(t!==null)solid=Math.min(solid,t);}if(hit!==null&&hit<=solid){const key=state.onFoot?'health':'integrity';state[key]=Math.max(0,(state[key]??100)-14);subdued=state[key]===0;this.onEvent({type:state[key]===0?'subdued':'hit',position:end,message:state[key]===0?'警察に制圧されました':state.onFoot?'被弾 · 遮蔽物へ':'車体に被弾 · 遮蔽物へ'});return false;}if(solid!==Infinity||b.life>1.05)return false;Object.assign(b,end);return true;});
 }
}
